const uint N = rows * I;
const uint base = thread_position_in_grid.x * 8;
if (base >= N) return;
if (base + 8 <= N) {
    float4 a0 = ld4(g + base), a1 = ld4(g + base + 4);
    float4 b0 = ld4(u + base), b1 = ld4(u + base + 4);
    st4(out + base, swg(a0, b0));
    st4(out + base + 4, swg(a1, b1));
} else {
    for (uint i = base; i < N; ++i) {
        float a = float(g[i]);
        out[i] = half(a / (1.0f + metal::fast::exp(-a)) * float(u[i]));
    }
}

