inline float4 ld4(const device half* p) { return float4(*(const device packed_half4*)p); }
inline float4 ld4(const constant half* p) { return float4(*(const constant packed_half4*)p); }
inline void st4(device half* p, float4 v) { *(device packed_half4*)p = packed_half4(half4(v)); }
inline float4 swg(float4 a, float4 b) { return a / (1.0f + metal::fast::exp(-a)) * b; }
